//! C ABI surface consumed by the native renderer's Swift code.
//!
//! Everything that crosses this boundary is `#[no_mangle] extern
//! "C"`. The header is generated by cbindgen at build time
//! (`build.rs`), then `make-release.sh` copies it into the
//! SwiftPM `CApfsFastindex` shim target.
//!
//! Design notes:
//!
//! - Strings cross the boundary as `*const c_char` (UTF-8,
//!   NUL-terminated). Swift wraps with `String(cString:)`. The
//!   Rust side owns each string for the lifetime of the
//!   enclosing handle (e.g. an `ApfsScan*` keeps all its path
//!   strings alive until `apfs_scan_free` runs).
//! - Bulk buffers (entry lists, cell lists, tree-list rows) are
//!   exposed as `(*const Item, usize)` pairs so Swift reads
//!   them as `UnsafeBufferPointer` without per-item FFI traffic.
//! - Every "new" function has a matching `_free` that the Swift
//!   side calls in `deinit`. Ownership rule: the caller of `new`
//!   is responsible for `_free`.
//! - Optional integer fields use the sentinel `u64::MAX` (or
//!   `i64::MIN` where applicable) for `None`. Cleaner than a
//!   parallel "has-this-field" bool from a FFI standpoint;
//!   Swift maps the sentinel back to `nil` on the wrapper side.
//!
//! # Pointer contract
//!
//! Non-NULL handles must be the original pointers returned by this module.
//! Callers must not mutate their contents or free them while a call or a
//! borrowed view is using them. Borrowed strings and buffers must not be
//! modified or freed by the caller. Each owning handle is freed exactly once
//! with its matching function, after all users and borrowed views are done.

use std::collections::HashMap;
use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int};
use std::ptr;

use crate::diag;
use crate::ext_summary::ExtSummary;
use crate::render::{render_cells, ApfsCell, ApfsLayout, HitGrid, Metric};
use crate::tree::{Tree, NODE_INVALID};
use crate::{fallback_scan_path_with_options, FallbackOptions, ProgressEvent};

/// Run `f` inside a `catch_unwind` barrier and return `sentinel`
/// if a Rust panic is caught. Every `#[no_mangle] extern "C" fn`
/// in this module wraps its body in this helper. Without it, a
/// panic in Rust code (parser asserts, index-out-of-range, etc.)
/// would unwind across the C ABI into the Swift caller, which is
/// undefined behavior — the SwiftUI app gets memory corruption
/// or an abort, not a graceful error path.
///
/// `panic = "abort"` is set workspace-wide in the release profile
/// as a defence-in-depth backstop, so this wrapper is the
/// guaranteed source-level barrier on debug builds (where
/// unwinding is on) and a no-op on release builds (which abort
/// before unwinding ever reaches us). Either way the C caller
/// never sees a partial-unwind state.
///
/// `AssertUnwindSafe` is required because most of our FFI bodies
/// capture references / `*mut` pointers that don't implement
/// `UnwindSafe` automatically; the bodies are short and don't
/// leave shared state inconsistent if they panic.
#[inline]
fn ffi_guard<R>(sentinel: R, f: impl FnOnce() -> R) -> R {
    // First call across the FFI installs the panic hook (idempotent
    // via `Once` inside `diag`). Cheap on subsequent calls — one
    // atomic check on a static.
    diag::install_panic_hook();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(r) => r,
        // Panic payload was already captured into the thread-local
        // `LAST_ERROR` and appended to the log file by the panic
        // hook before unwinding reached us here — see `diag.rs`.
        // We just swallow the `Err(Box<dyn Any>)` and return the
        // fail-closed sentinel; Swift's next call to
        // `apfs_last_error()` will hand the message back.
        Err(_) => sentinel,
    }
}

// ─────────────────────────────────────────────────────────────
// Diagnostic accessors
// ─────────────────────────────────────────────────────────────

/// Return a `*const c_char` pointing at the most-recent error
/// message recorded on this thread, or NULL if there is none.
/// Reading clears the slot — the contract is "one read per
/// failure," matching Swift's `Scan.lastError()` semantics.
///
/// Lifetime: valid until the next call on the same thread that
/// records a new error. Swift wraps with `String(cString:)` and
/// owns the copy from that point on. NUL-terminated UTF-8.
#[no_mangle]
pub extern "C" fn apfs_last_error() -> *const c_char {
    // No `ffi_guard` here: this accessor must never recurse
    // into the panic-capture path. It only reads thread-locals
    // and returns a pointer; the only way it could panic is an
    // allocator failure inside `CString::new`, which is fatal
    // anyway.
    diag::last_error_cstr()
}

/// Return a `*const c_char` pointing at the resolved log-file
/// path (`~/Library/Logs/apfs-fastindex.log` on macOS) the panic
/// hook writes to. NULL if the hook hasn't been installed yet
/// (won't happen after the first scan-related FFI call). The
/// pointer lives for the process lifetime — Swift can cache it.
#[no_mangle]
pub extern "C" fn apfs_log_path() -> *const c_char {
    diag::install_panic_hook();
    diag::log_path_cstr()
}

// ─────────────────────────────────────────────────────────────
// Phase 1 sanity-check surface
// ─────────────────────────────────────────────────────────────

/// Returns a constant integer the Swift side can assert on to
/// confirm the FFI bridge is wired correctly. The number is the
/// MWP-trivia answer; if it changes, something has gone wrong
/// with name mangling or the static-lib search path.
#[no_mangle]
pub extern "C" fn apfs_hello() -> c_int {
    ffi_guard(0, move || 42)
}

/// Returns the apfs-fastindex crate version as a NUL-terminated
/// UTF-8 string (static, so the pointer is valid for the
/// lifetime of the process — Swift must not free it). The
/// version is baked at compile time from `Cargo.toml`.
#[no_mangle]
pub extern "C" fn apfs_version() -> *const c_char {
    ffi_guard(ptr::null(), move || {
        // `concat!` produces a static `&'static str`; appending a
        // trailing `\0` byte and exposing the data pointer is the
        // idiomatic way to hand a C string out of Rust without an
        // allocation.
        static VERSION: &str = concat!(env!("CARGO_PKG_VERSION"), "\0");
        VERSION.as_ptr() as *const c_char
    })
}

// ─────────────────────────────────────────────────────────────
// Phase 2: scan FFI
// ─────────────────────────────────────────────────────────────

/// Opaque handle representing a completed fallback scan. Owns
/// the entry buffer, the indexed tree, and supporting strings.
/// Swift sees a `*mut ApfsScan` and must call `apfs_scan_free`
/// when done.
pub struct ApfsScan {
    pub(crate) output: crate::FallbackScanOutput,
    /// Indexed tree over `output.parser_output.entries`.
    /// Phase 3 builds this at scan time so the renderer can
    /// query it by path without re-scanning the entry list.
    pub(crate) tree: Tree,
    /// Lazy cache for `apfs_scan_node_path`. `TreeNode` itself no
    /// longer stores the materialised path (round 4 of the perf
    /// pass — saved 16 B per node by computing on demand); the
    /// FFI populates this cache on first query and then returns
    /// the borrowed slice on every subsequent call for the same
    /// `idx`. `Mutex` rather than `RefCell` so the FFI is safe
    /// to call from multiple Swift threads (the Swift bridge
    /// doesn't actually do that today, but the C signature
    /// doesn't gate against it).
    path_cache: std::sync::Mutex<HashMap<u32, Box<str>>>,
    // CStrings keep the NUL-terminated bytes alive for the
    // lifetime of the scan. Pointers handed to Swift point
    // into these — Swift must not free them; they go away
    // when `apfs_scan_free` drops the box.
    correctness_claim: CString,
    source_kind: CString,
    source_requested_path: CString,
    /// True iff *any* entry has `allocated_size = Some(_)`.
    /// The Swift UI toggles the "Allocated" metric chip off
    /// when this is false.
    allocated_available: bool,
    /// True iff *any* entry has `real_size = Some(_)`. The Swift UI
    /// toggles the "Real" metric chip off when this is false. Raw mode
    /// (EX-27) populates this; the fallback walker also sets it
    /// (`real_size == allocated_size`) so the metric is observably
    /// available with the same coverage as Allocated.
    real_available: bool,
}

/// Sentinel for "no allocated total" (SR-019 None-collapse) and
/// "no real total" (EX-27 None-collapse). Pre-baked at the C-ABI
/// boundary because Option<u64> doesn't cross unmodified.
const APFS_ALLOCATED_TOTAL_UNCLAIMED: u64 = u64::MAX;
const APFS_REAL_TOTAL_UNCLAIMED: u64 = u64::MAX;

/// Scan a directory and return an owning `ApfsScan*`. `threads`
/// of 0 uses the default (min of physical-cpu and 4 per EX-25).
/// `cross_mounts` toggles whether the walker descends into
/// directories on a different device than the root.
///
/// Returns `NULL` on:
///   - `path` is NULL
///   - `path` is not valid UTF-8
///   - the scan returns an error (bad source, permission denial
///     at root, etc.)
///
/// # Safety
/// `path` must be NULL or a valid, unmodified NUL-terminated C string for
/// the duration of the call. Free a non-NULL result with `apfs_scan_free`.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_directory(
    path: *const c_char,
    threads: u32,
    cross_mounts: bool,
) -> *mut ApfsScan {
    ffi_guard(ptr::null_mut(), move || {
        // Thin wrapper: the no-progress path is just the
        // with-progress path called with a NULL callback. Keeps the
        // post-scan finalize logic in one place
        // (`finalize_scan_handle`).
        // SAFETY: the caller supplies the path contract, and no callback runs.
        unsafe {
            apfs_scan_directory_with_progress(path, threads, cross_mounts, None, ptr::null_mut())
        }
    })
}

/// C ABI signature for the progress callback the Swift side
/// hands to `apfs_scan_directory_with_progress`. The Rust
/// fallback walker fires events from a dedicated background
/// thread (one event ≈ every 250 ms while the scan runs, plus
/// a final `terminal=true` event when scanning finishes); the
/// callback must be safe to invoke from that thread.
/// Wrapped in `Option<...>` so the C ABI is `void (*)(...)` (a
/// nullable function pointer); cbindgen collapses
/// `Option<extern "C" fn>` to a plain function-pointer typedef
/// when written this way.
// `bytes` is the cumulative `logical_size` sum for entries
// scanned so far — drives a determinate progress bar (numerator)
// against a volume-capacity denominator on the Swift side.
pub type ApfsProgressCallback = Option<
    extern "C" fn(
        scanned: u64,
        skipped: u64,
        bytes: u64,
        elapsed_ms: u64,
        terminal: bool,
        userdata: *mut std::os::raw::c_void,
    ),
>;

/// Newtype around the raw userdata pointer so we can opt into
/// `Send` for the closure that moves it into the parallel
/// walker. Swift caller is responsible for actual thread
/// safety — typically the userdata is an `Unmanaged.toOpaque()`
/// reference to a Swift box.
struct ProgressUserdata(*mut std::os::raw::c_void);
unsafe impl Send for ProgressUserdata {}

/// Like `apfs_scan_directory` but with a live progress callback.
/// `progress_fn` is invoked from a background thread roughly
/// every 250 ms during the scan; the final event has
/// `terminal == true`. Passing NULL for `progress_fn` is
/// equivalent to calling `apfs_scan_directory` (no progress
/// events).
///
/// # Safety
/// `path` must be NULL or a valid, unmodified NUL-terminated C string until
/// this call returns. A callback must not unwind and must be safe on any
/// walker thread. Its `userdata` must remain valid and thread-safe as required
/// by that callback until return. Free a non-NULL result with `apfs_scan_free`.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_directory_with_progress(
    path: *const c_char,
    threads: u32,
    cross_mounts: bool,
    progress_fn: ApfsProgressCallback,
    userdata: *mut std::os::raw::c_void,
) -> *mut ApfsScan {
    ffi_guard(ptr::null_mut(), move || {
        if path.is_null() {
            diag::set_last_error("path argument is NULL");
            return ptr::null_mut();
        }
        let cstr = unsafe { CStr::from_ptr(path) };
        let path_str = match cstr.to_str() {
            Ok(s) => s,
            Err(e) => {
                diag::set_last_error(format!("path is not valid UTF-8: {}", e));
                return ptr::null_mut();
            }
        };
        let user = ProgressUserdata(userdata);
        let mut progress_closure = move |event: ProgressEvent| {
            // Rebind to a reference so disjoint-captures captures the
            // whole `ProgressUserdata` (which is `Send` via the unsafe
            // impl above) rather than projecting `user.0`, which would
            // be a bare `*mut c_void` and not `Send`.
            let user = &user;
            if let Some(cb) = progress_fn {
                cb(
                    event.scanned,
                    event.skipped,
                    event.bytes,
                    event.elapsed.as_millis() as u64,
                    event.terminal,
                    user.0,
                );
            }
        };
        let progress_ref: Option<&mut (dyn FnMut(ProgressEvent) + Send)> = if progress_fn.is_some()
        {
            Some(&mut progress_closure)
        } else {
            None
        };
        let options = FallbackOptions {
            cross_mounts,
            progress: progress_ref,
            threads: if threads == 0 { 4 } else { threads as usize },
            // FFI consumers (the SwiftUI app) read subtree totals
            // from the indexed `Tree`, not from the legacy
            // `aggregates` Vec.
            skip_aggregates: true,
        };
        let output = match fallback_scan_path_with_options(path_str, options) {
            Ok(o) => o,
            Err(e) => {
                diag::set_last_error(format!("scan failed: {}", e));
                return ptr::null_mut();
            }
        };
        finalize_scan_handle(output)
    })
}

/// Shared post-scan handle construction. Called by both the
/// progress and no-progress entry points. Builds the indexed
/// tree, caches the `allocated_available` flag, packs paths
/// + claim into CStrings, and hands the box back.
fn finalize_scan_handle(output: crate::FallbackScanOutput) -> *mut ApfsScan {
    // These fields cross the ABI as C strings. Reject embedded NULs
    // instead of silently replacing the source or correctness claim
    // with an empty string when loading a malformed saved scan.
    let claim_c = match CString::new(output.correctness_claim.as_str()) {
        Ok(value) => value,
        Err(_) => {
            diag::set_last_error("scan correctness claim contains a NUL byte");
            return ptr::null_mut();
        }
    };
    let source_kind_c = match CString::new(output.parser_output.source.source_kind.as_str()) {
        Ok(value) => value,
        Err(_) => {
            diag::set_last_error("scan source kind contains a NUL byte");
            return ptr::null_mut();
        }
    };
    let source_requested_path_c = match CString::new(
        output
            .parser_output
            .source
            .requested_path
            .to_string_lossy()
            .as_bytes(),
    ) {
        Ok(value) => value,
        Err(_) => {
            diag::set_last_error("scan requested path contains a NUL byte");
            return ptr::null_mut();
        }
    };
    let tree = Tree::build(&output.parser_output.entries);
    let mut allocated_available = false;
    let mut real_available = false;
    for entry in &output.parser_output.entries {
        if entry.allocated_size.is_some() {
            allocated_available = true;
        }
        if entry.real_size.is_some() {
            real_available = true;
        }
        if allocated_available && real_available {
            break;
        }
    }
    Box::into_raw(Box::new(ApfsScan {
        output,
        tree,
        path_cache: std::sync::Mutex::new(HashMap::new()),
        correctness_claim: claim_c,
        source_kind: source_kind_c,
        source_requested_path: source_requested_path_c,
        allocated_available,
        real_available,
    }))
}

/// True iff `path` resolves to a filesystem mounted as a
/// snapshot (statfs.f_flags & MNT_SNAPSHOT). Returns 0 for any
/// error (path NULL, not UTF-8, statfs failed) so the caller
/// treats a non-snapshot as the safe default.
///
/// EX-29 follow-up: the Swift bridge can't reach Darwin's
/// `statfs(_:_:)` function unambiguously through the overlay
/// (name collision with `struct statfs`). Calling out to this
/// FFI is the workaround.
///
/// # Safety
/// `path` must be NULL or a valid, unmodified NUL-terminated C string for
/// the duration of the call.
#[no_mangle]
pub unsafe extern "C" fn apfs_is_snapshot_path(path: *const c_char) -> i32 {
    ffi_guard(0, move || {
        if path.is_null() {
            return 0;
        }
        let c_str = unsafe { std::ffi::CStr::from_ptr(path) };
        let Ok(rust_path) = c_str.to_str() else {
            return 0;
        };
        let Ok(c_path) = std::ffi::CString::new(rust_path) else {
            return 0;
        };
        let mut buf: libc::statfs = unsafe { std::mem::zeroed() };
        let rc = unsafe { libc::statfs(c_path.as_ptr(), &mut buf as *mut libc::statfs) };
        if rc != 0 {
            return 0;
        }
        // MNT_SNAPSHOT from <sys/mount.h>: 0x40000000.
        const MNT_SNAPSHOT: u32 = 0x4000_0000;
        if buf.f_flags & MNT_SNAPSHOT != 0 {
            1
        } else {
            0
        }
    })
}

/// Load an ApfsScan from a previously-emitted msgpack file.
///
/// The privileged-subprocess "Scan as Administrator…" flow
/// runs the CLI's JSON-line server through Authorization
/// Services. The helper writes its `FallbackScanOutput` to a
/// helper-chosen tempfile, transfers the completed mode-0600
/// file to the GUI's UID, and returns the path. The GUI calls
/// this FFI to build the same `ApfsScan` handle as an in-process
/// scan.
///
/// Returns `NULL` on:
/// - `path` is NULL or not valid UTF-8
/// - the file can't be opened or read
/// - the opened object is not a regular file, or on macOS the
///   final path component is a symlink
/// - the msgpack blob fails to decode as `FallbackScanOutput`
/// - decoded metadata for a C-string accessor contains a NUL byte
///
/// On any of those, the caller can read `apfs_last_error` for a
/// human-readable diagnostic.
///
/// # Safety
/// `path` must be NULL or a valid, unmodified NUL-terminated C string for
/// the duration of the call. Free a non-NULL result with `apfs_scan_free`.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_from_msgpack_file(path: *const c_char) -> *mut ApfsScan {
    ffi_guard(ptr::null_mut(), move || {
        if path.is_null() {
            crate::diag::set_last_error("apfs_scan_from_msgpack_file: path is NULL");
            return ptr::null_mut();
        }
        let cstr = unsafe { std::ffi::CStr::from_ptr(path) };
        let Ok(rust_path) = cstr.to_str() else {
            crate::diag::set_last_error("apfs_scan_from_msgpack_file: path is not valid UTF-8");
            return ptr::null_mut();
        };
        let bytes = match read_scan_msgpack_file(std::path::Path::new(rust_path)) {
            Ok(b) => b,
            Err(err) => {
                crate::diag::set_last_error(format!(
                    "apfs_scan_from_msgpack_file: read {rust_path}: {err}"
                ));
                return ptr::null_mut();
            }
        };
        let output: crate::FallbackScanOutput = match rmp_serde::from_slice(&bytes) {
            Ok(o) => o,
            Err(err) => {
                crate::diag::set_last_error(format!(
                    "apfs_scan_from_msgpack_file: decode {rust_path}: {err}"
                ));
                return ptr::null_mut();
            }
        };
        // Deserialization owns every string. Release the transport
        // allocation before the indexed tree allocates its buffers.
        drop(bytes);
        finalize_scan_handle(output)
    })
}

/// Read through the same descriptor that we inspect. This generic loader
/// accepts ordinary CLI output regardless of mode or owner. The private
/// helper's stricter ownership checks remain the GUI caller's responsibility.
fn read_scan_msgpack_file(path: &std::path::Path) -> std::io::Result<Vec<u8>> {
    use std::io::Read;
    let mut options = std::fs::OpenOptions::new();
    options.read(true);
    #[cfg(target_os = "macos")]
    {
        use std::os::unix::fs::OpenOptionsExt;
        // Nonblocking open prevents a replaced FIFO from hanging before
        // fstat can reject it. It does not affect regular-file reads.
        options.custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK | libc::O_CLOEXEC);
    }
    let mut file = options.open(path)?;
    let metadata = file.metadata()?;
    if !metadata.is_file() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "scan input is not a regular file",
        ));
    }
    let mut bytes = Vec::new();
    let size = usize::try_from(metadata.len()).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "scan input exceeds the address space",
        )
    })?;
    bytes
        .try_reserve_exact(size)
        .map_err(|err| std::io::Error::new(std::io::ErrorKind::OutOfMemory, err))?;
    file.read_to_end(&mut bytes)?;
    Ok(bytes)
}

/// Drop a scan handle. Idempotent on NULL.
///
/// # Safety
/// `scan` must be NULL or an owning scan handle returned by this module,
/// not previously freed. All calls and borrowed views using it must be done.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_free(scan: *mut ApfsScan) {
    ffi_guard((), move || {
        if scan.is_null() {
            return;
        }
        // SAFETY: the caller transfers an original, not-yet-freed scan handle.
        unsafe {
            drop(Box::from_raw(scan));
        }
    })
}

/// Number of `NamespaceEntry` rows in the scan.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_entry_count(scan: *const ApfsScan) -> u64 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        s.output.parser_output.entries.len() as u64
    })
}

/// Sum of `entry.logical_size` across the whole scan. Reads off
/// the tree root's pre-computed aggregate.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_logical_total(scan: *const ApfsScan) -> u64 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        s.tree.nodes.first().map(|r| r.value_logical).unwrap_or(0)
    })
}

/// Sum of `entry.allocated_size` across the whole scan, or
/// `APFS_ALLOCATED_TOTAL_UNCLAIMED` (`u64::MAX`) when *any* row
/// had `allocated_size = None` (SR-019 None-collapse). Reads off
/// the tree root's pre-computed aggregate.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_allocated_total(scan: *const ApfsScan) -> u64 {
    ffi_guard(APFS_ALLOCATED_TOTAL_UNCLAIMED, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return APFS_ALLOCATED_TOTAL_UNCLAIMED;
        };
        s.tree
            .nodes
            .first()
            .and_then(|r| r.value_allocated)
            .unwrap_or(APFS_ALLOCATED_TOTAL_UNCLAIMED)
    })
}

/// Sum of `entry.real_size` (EX-27 clone-deduplicated allocated
/// bytes) across the whole scan, or `APFS_REAL_TOTAL_UNCLAIMED`
/// (`u64::MAX`) when *any* row had `real_size = None`. Reads off
/// the tree root's pre-computed aggregate.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_real_total(scan: *const ApfsScan) -> u64 {
    ffi_guard(APFS_REAL_TOTAL_UNCLAIMED, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return APFS_REAL_TOTAL_UNCLAIMED;
        };
        s.tree
            .nodes
            .first()
            .and_then(|r| r.value_real)
            .unwrap_or(APFS_REAL_TOTAL_UNCLAIMED)
    })
}

/// `true` iff at least one entry in the scan has
/// `real_size = Some(_)`. The Swift UI toggles the "Real" metric
/// chip off when this is false. Fallback mode populates this same
/// as `allocated_size` (no refcount info from POSIX), so on a
/// well-formed scan both are typically `true`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_real_available(scan: *const ApfsScan) -> bool {
    ffi_guard(false, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return false;
        };
        s.real_available
    })
}

// ─────────────────────────────────────────────────────────────
// Phase 3a: tree query FFI
// ─────────────────────────────────────────────────────────────

/// Total number of nodes in the tree (root + every directory +
/// every leaf). Differs from `apfs_scan_entry_count` because the
/// tree also has synthesized intermediate directories.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_count(scan: *const ApfsScan) -> u32 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        s.tree.nodes.len() as u32
    })
}

/// Search result handle returned by `apfs_scan_search_names`.
/// Carries two parallel views into the same search:
///
/// - `indices`: the **full keep-set** — every matching node
///   plus every ancestor plus the root, sorted. This is what
///   a hierarchical tree-list UI needs to render matches in
///   context.
/// - `matches`: just the nodes whose name matched the query,
///   sorted. A flat-list "search results" UI uses this to
///   render matches without forcing an auto-expansion of the
///   entire ancestor chain (which on a single-letter query
///   like `"n"` can be 1 M+ nodes, blowing up any
///   tree-walking renderer).
///
/// The Swift bridge reads both via dedicated accessors and
/// must call `apfs_search_results_free` exactly once.
pub struct ApfsSearchResults {
    indices: Vec<u32>,
    matches: Vec<u32>,
}

/// Canonical caseless substring search across every node's display name.
/// Returns matching node indices, their ancestors, and the root, so callers
/// can render a connected tree. Display names and paths remain unchanged.
///
/// Names use a contiguous search-key buffer built once per scan. The query
/// uses the same folding and one reusable substring finder. Ancestor walks
/// stop at an already-kept node, bounding that work by the unique keep-set.
///
/// Returns `NULL` on:
/// - `scan` or `query` NULL
/// - `query` not valid UTF-8
/// - `query` empty (caller treats "" as "no filter" and skips
///   this call entirely; returning a sentinel handle would be
///   wasteful)
///
/// The result handle owns its indices buffer; Swift must call
/// `apfs_search_results_free` when done.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module, not mutated
/// or freed during the call. `query` must be NULL or a valid, unmodified
/// NUL-terminated C string during the call. Free a non-NULL result with
/// `apfs_search_results_free`. The result does not borrow from `scan`.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_search_names(
    scan: *const ApfsScan,
    query: *const c_char,
) -> *mut ApfsSearchResults {
    use rustc_hash::FxHashSet;
    ffi_guard(std::ptr::null_mut(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return std::ptr::null_mut();
        };
        if query.is_null() {
            return std::ptr::null_mut();
        }
        let c_query = unsafe { CStr::from_ptr(query) };
        let Ok(q_str) = c_query.to_str() else {
            return std::ptr::null_mut();
        };
        if q_str.is_empty() {
            return std::ptr::null_mut();
        }
        let mut q_lower = Vec::with_capacity(q_str.len());
        crate::search::append_folded(q_str, &mut q_lower);
        let finder = memchr::memmem::Finder::new(&q_lower);
        let buf = &s.tree.names_lower_buf;
        let offsets = &s.tree.names_lower_offsets;
        let nodes = &s.tree.nodes;

        // Tight loop over the flat name buffer. Each
        // `finder.find` is a SIMD-accelerated substring
        // scan over the slice bounded by adjacent offsets.
        // Memory access is sequential: we walk `offsets`
        // and `buf` from start to end, which the prefetcher
        // streams through.
        let mut keep: FxHashSet<u32> = FxHashSet::default();
        let mut matches: Vec<u32> = Vec::new();
        // Root always in (so the tree renders even when zero
        // matches).
        keep.insert(0);
        let n_nodes = nodes.len();
        for i in 0..n_nodes {
            let start = offsets[i] as usize;
            let end = offsets[i + 1] as usize;
            if finder.find(&buf[start..end]).is_some() {
                matches.push(i as u32);
                // Walk the parent chain and insert every
                // ancestor. `insert` returns false the
                // moment we hit a node already in the set
                // — the rest of the chain is also in, so
                // we stop. Total ancestor work is
                // O(unique kept nodes), not
                // O(matches × depth).
                let mut n: Option<u32> = Some(i as u32);
                while let Some(curr) = n {
                    if !keep.insert(curr) {
                        break;
                    }
                    n = nodes[curr as usize].parent;
                }
            }
        }
        // Return both views sorted. The keep-set is for
        // hierarchical rendering; the matches list is for
        // flat "search results" rendering (cheap to walk even
        // when the keep-set is huge).
        let mut indices: Vec<u32> = keep.into_iter().collect();
        indices.sort_unstable();
        // `matches` is already in tree order from the
        // sequential loop above — already sorted.
        Box::into_raw(Box::new(ApfsSearchResults { indices, matches }))
    })
}

/// Number of matching node indices in `results`. `0` on NULL.
///
/// # Safety
/// `results` must be NULL or a live search-results handle from this module.
/// It must not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_search_results_count(results: *const ApfsSearchResults) -> usize {
    ffi_guard(0, move || {
        let Some(r) = (unsafe { results.as_ref() }) else {
            return 0;
        };
        r.indices.len()
    })
}

/// Pointer to the matching-node-indices buffer. Length given
/// by `apfs_search_results_count`. Buffer is valid until
/// `apfs_search_results_free` is called.
///
/// # Safety
/// `results` must be NULL or a live search-results handle from this module.
/// Keep it alive and unmodified while using the returned borrowed buffer.
#[no_mangle]
pub unsafe extern "C" fn apfs_search_results_indices(
    results: *const ApfsSearchResults,
) -> *const u32 {
    ffi_guard(std::ptr::null(), move || {
        let Some(r) = (unsafe { results.as_ref() }) else {
            return std::ptr::null();
        };
        r.indices.as_ptr()
    })
}

/// Drop the search-results handle. Idempotent on NULL.
///
/// # Safety
/// `results` must be NULL or an owning handle from `apfs_scan_search_names`,
/// not previously freed. All calls and borrowed views using it must be done.
#[no_mangle]
pub unsafe extern "C" fn apfs_search_results_free(results: *mut ApfsSearchResults) {
    if results.is_null() {
        return;
    }
    // SAFETY: caller-supplied pointer originated from
    // `Box::into_raw` in `apfs_scan_search_names`; we reclaim
    // ownership and drop it. Repeat calls with the same
    // pointer are UB on the Swift side (per the standard
    // `_free` contract).
    let _ = unsafe { Box::from_raw(results) };
}

/// Number of nodes whose name matched the query (i.e. the
/// "real" matches, not the inflated keep-set). `0` on NULL.
///
/// # Safety
/// `results` must be NULL or a live search-results handle from this module.
/// It must not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_search_results_match_count(
    results: *const ApfsSearchResults,
) -> usize {
    ffi_guard(0, move || {
        let Some(r) = (unsafe { results.as_ref() }) else {
            return 0;
        };
        r.matches.len()
    })
}

/// Pointer to the matches buffer (`u32` per entry, length
/// from `apfs_search_results_match_count`). Sorted in tree
/// (node-index) order. Valid until `apfs_search_results_free`.
///
/// # Safety
/// `results` must be NULL or a live search-results handle from this module.
/// Keep it alive and unmodified while using the returned borrowed buffer.
#[no_mangle]
pub unsafe extern "C" fn apfs_search_results_match_indices(
    results: *const ApfsSearchResults,
) -> *const u32 {
    ffi_guard(std::ptr::null(), move || {
        let Some(r) = (unsafe { results.as_ref() }) else {
            return std::ptr::null();
        };
        r.matches.as_ptr()
    })
}

/// Sentinel returned by `apfs_scan_node_index_for_path` (and
/// future phase-3 hit-test FFIs) when no node matches. Matches
/// `crate::tree::NODE_INVALID == u32::MAX`.
pub const APFS_NODE_INVALID: u32 = u32::MAX;

/// Look up a node by its absolute logical path. The empty string
/// (and `"/"`) maps to the synthesised root (index 0). Returns
/// `APFS_NODE_INVALID` if no such node exists.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module, not mutated
/// or freed during the call. `path` must be NULL or a valid, unmodified
/// NUL-terminated C string for the duration of the call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_index_for_path(
    scan: *const ApfsScan,
    path: *const c_char,
) -> u32 {
    ffi_guard(APFS_NODE_INVALID, move || {
        if path.is_null() {
            return APFS_NODE_INVALID;
        }
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return APFS_NODE_INVALID;
        };
        let cstr = unsafe { CStr::from_ptr(path) };
        let p = match cstr.to_str() {
            Ok(p) => p,
            Err(_) => return APFS_NODE_INVALID,
        };
        let idx = s.tree.node_index_for_path(p);
        if idx == NODE_INVALID {
            APFS_NODE_INVALID
        } else {
            idx
        }
    })
}

/// Number of immediate children of the given node.
/// `apfs_scan_node_child_count(s, root) == top-level dir/file
/// count`. Returns 0 for invalid indices.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_child_count(scan: *const ApfsScan, idx: u32) -> u32 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return 0;
        }
        s.tree.nodes[idx as usize].children_count
    })
}

/// Per-node aggregate read by Swift's status bar. Pre-computed
/// post-order at `Tree::build` time; constant-time lookup.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_value_logical(scan: *const ApfsScan, idx: u32) -> u64 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return 0;
        }
        s.tree.nodes[idx as usize].value_logical
    })
}

/// `value_allocated` for the node, or
/// `APFS_ALLOCATED_TOTAL_UNCLAIMED` (`u64::MAX`) when SR-019
/// None-collapse fired anywhere in this subtree.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_value_allocated(scan: *const ApfsScan, idx: u32) -> u64 {
    ffi_guard(APFS_ALLOCATED_TOTAL_UNCLAIMED, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return APFS_ALLOCATED_TOTAL_UNCLAIMED;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return APFS_ALLOCATED_TOTAL_UNCLAIMED;
        }
        s.tree.nodes[idx as usize]
            .value_allocated
            .unwrap_or(APFS_ALLOCATED_TOTAL_UNCLAIMED)
    })
}

/// Item count for the node — number of non-directory descendants.
/// `apfs_scan_node_item_count(s, root) == files+symlinks total`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_item_count(scan: *const ApfsScan, idx: u32) -> u64 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return 0;
        }
        s.tree.nodes[idx as usize].item_count
    })
}

/// Borrowed (ptr, len) pair pointing into a `Tree`-owned UTF-8
/// string. Valid for the lifetime of the enclosing `ApfsScan`.
/// `bytes` is *not* NUL-terminated — Swift constructs `String`
/// via `Data(bytes:count:)` + `String(data:encoding:)`.
///
/// We don't pay for CString-style NUL-terminated copies for
/// every node because at /-scale that's ~150 MB of duplicate
/// path storage; the borrowed pointer trades one extra Swift
/// API call for zero allocation.
#[repr(C)]
#[derive(Copy, Clone)]
pub struct ApfsPathRef {
    pub bytes: *const u8,
    pub len: u64,
}

/// Borrow the node's absolute logical path. Returns a null
/// pointer + zero length for invalid indices.
///
/// The path isn't stored on `TreeNode` (round 4 of the perf
/// pass dropped it — saved 16 B per node). We compute on demand
/// via parent-walk and cache the materialised `Box<str>` in
/// `ApfsScan.path_cache`. Pointer lifetime matches the scan
/// handle: the cache owns the bytes until `apfs_scan_free`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed bytes.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_path(scan: *const ApfsScan, idx: u32) -> ApfsPathRef {
    ffi_guard(
        ApfsPathRef {
            bytes: ptr::null(),
            len: 0,
        },
        move || {
            let null_ref = ApfsPathRef {
                bytes: ptr::null(),
                len: 0,
            };
            let Some(s) = (unsafe { scan.as_ref() }) else {
                return null_ref;
            };
            if (idx as usize) >= s.tree.nodes.len() {
                return null_ref;
            }
            // Recover from a poisoned mutex by taking the inner
            // guard anyway. The `path_cache` only holds owned
            // `Box<str>` values that don't observe any external
            // invariants — a panic mid-insert can't leave them in
            // a partially-constructed state — so the audit's #N1
            // "one panic → permanent DoS on all path queries"
            // amplification doesn't apply. Pre-fix this was
            // `.unwrap()`, which returned the FFI sentinel
            // `(NULL, 0)` for every subsequent `apfs_scan_node_path`
            // on the same scan handle.
            let mut cache = s
                .path_cache
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            // The entry stays in the HashMap for the lifetime of
            // `ApfsScan`, so the borrowed slice is valid until
            // `apfs_scan_free`. The `&'static str` lifetime extension
            // below is justified by that invariant; we only hand the
            // pointer + length across the FFI boundary, never a
            // reference Rust has to verify.
            let entry = cache.entry(idx).or_insert_with(|| s.tree.compute_path(idx));
            let bytes = entry.as_ptr();
            let len = entry.len() as u64;
            ApfsPathRef { bytes, len }
        },
    )
}

/// Borrow the node's last path component (display name). Like
/// `apfs_scan_node_path` but returns just the leaf basename.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed bytes.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_name(scan: *const ApfsScan, idx: u32) -> ApfsPathRef {
    ffi_guard(
        ApfsPathRef {
            bytes: ptr::null(),
            len: 0,
        },
        move || {
            let null_ref = ApfsPathRef {
                bytes: ptr::null(),
                len: 0,
            };
            let Some(s) = (unsafe { scan.as_ref() }) else {
                return null_ref;
            };
            if (idx as usize) >= s.tree.nodes.len() {
                return null_ref;
            }
            let n = &s.tree.nodes[idx as usize].name;
            ApfsPathRef {
                bytes: n.as_ptr(),
                len: n.len() as u64,
            }
        },
    )
}

/// Parent index for `idx`, or `APFS_NODE_INVALID` for the root
/// (no parent) or an invalid `idx`. Used by Swift's breadcrumb
/// construction (walk parent chain from `currentNode` to root).
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_parent(scan: *const ApfsScan, idx: u32) -> u32 {
    ffi_guard(APFS_NODE_INVALID, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return APFS_NODE_INVALID;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return APFS_NODE_INVALID;
        }
        s.tree.nodes[idx as usize]
            .parent
            .unwrap_or(APFS_NODE_INVALID)
    })
}

/// Returns the node's `EntryKind` as a u32 discriminant:
///   0 = dir, 1 = file, 2 = symlink, 3 = other, 0xff = invalid
/// Swift maps back to a `Scan.NodeKind` enum.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_kind(scan: *const ApfsScan, idx: u32) -> u32 {
    ffi_guard(0xff, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0xff;
        };
        if (idx as usize) >= s.tree.nodes.len() {
            return 0xff;
        }
        match s.tree.nodes[idx as usize].kind {
            crate::EntryKind::Dir => 0,
            crate::EntryKind::File => 1,
            crate::EntryKind::Symlink => 2,
            crate::EntryKind::Other => 3,
        }
    })
}

/// Borrowed (ptr, count) slice of child node indices. Lifetime
/// is tied to the enclosing `ApfsScan`; Swift reads as
/// `UnsafeBufferPointer<UInt32>` with no copy.
#[repr(C)]
#[derive(Copy, Clone)]
pub struct ApfsU32Slice {
    pub items: *const u32,
    pub count: u64,
}

/// Borrow the slice of immediate-child node indices for `idx`.
/// Returns an empty slice for invalid indices or leaves.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed buffer.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_node_children(scan: *const ApfsScan, idx: u32) -> ApfsU32Slice {
    ffi_guard(
        ApfsU32Slice {
            items: ptr::null(),
            count: 0,
        },
        move || {
            let null_slice = ApfsU32Slice {
                items: ptr::null(),
                count: 0,
            };
            let Some(s) = (unsafe { scan.as_ref() }) else {
                return null_slice;
            };
            if (idx as usize) >= s.tree.nodes.len() {
                return null_slice;
            }
            let children = s.tree.children_of(idx);
            if children.is_empty() {
                return null_slice;
            }
            ApfsU32Slice {
                items: children.as_ptr(),
                count: children.len() as u64,
            }
        },
    )
}

// ─────────────────────────────────────────────────────────────
// Phase 3b/c: treemap layout — opaque handle + hit-test
// ─────────────────────────────────────────────────────────────

// Re-export the cell record under the C ABI so cbindgen picks
// up the symbol. The actual struct lives in `crate::render`.
pub use crate::render::ApfsCell as ApfsCellRecord;

/// Borrowed view over a laid-out cell array. Valid for the
/// lifetime of the enclosing `ApfsLayout`; Swift reads via
/// `UnsafeBufferPointer<ApfsCell>(start: cells, count: count)`
/// without a copy.
#[repr(C)]
#[derive(Copy, Clone)]
pub struct ApfsCellSlice {
    pub cells: *const ApfsCell,
    pub count: u64,
}

/// Sentinel returned by `apfs_layout_hit_test` when no cell
/// covers the point. Matches `crate::tree::NODE_INVALID`
/// (`u32::MAX`).
pub const APFS_CELL_INVALID: u32 = u32::MAX;

/// Lay out the subtree rooted at `node_idx` inside a viewport of
/// (`width`, `height`) CSS pixels. `max_depth = 0` is the
/// no-truncation sentinel (render every descendant; cull only by
/// `MIN_PIXEL_AREA = 1`).
///
/// `metric`:
///   - `0` → logical
///   - `1` → allocated
///
/// The returned handle owns both the cell array and the
/// `HitGrid` for hit-testing. Always pair with
/// `apfs_layout_free`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module, not mutated
/// or freed during the call. Free a non-NULL result with `apfs_layout_free`.
/// The result does not borrow from `scan`.
#[no_mangle]
pub unsafe extern "C" fn apfs_layout_new(
    scan: *const ApfsScan,
    node_idx: u32,
    max_depth: u32,
    metric: u32,
    width: f32,
    height: f32,
) -> *mut ApfsLayout {
    ffi_guard(ptr::null_mut(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return ptr::null_mut();
        };
        let metric_enum = if metric == 1 {
            Metric::Allocated
        } else {
            Metric::Logical
        };
        let cells = render_cells(
            &s.tree,
            node_idx,
            max_depth,
            metric_enum,
            width as f64,
            height as f64,
        );
        if cells.is_empty() {
            return ptr::null_mut();
        }
        let boxed: Box<[ApfsCell]> = cells.into_boxed_slice();
        let hit_grid = HitGrid::build(&boxed, width, height);
        let layout = Box::new(ApfsLayout {
            cells: boxed,
            hit_grid,
        });
        Box::into_raw(layout)
    })
}

/// Reclaim a layout previously returned by `apfs_layout_new`.
/// Idempotent on NULL.
///
/// # Safety
/// `layout` must be NULL or an owning handle from `apfs_layout_new`, not
/// previously freed. All calls and borrowed views using it must be done.
#[no_mangle]
pub unsafe extern "C" fn apfs_layout_free(layout: *mut ApfsLayout) {
    ffi_guard((), move || {
        if layout.is_null() {
            return;
        }
        // SAFETY: caller obtained `layout` from `apfs_layout_new`
        // and has not yet freed it. Box drop releases cells +
        // hit_grid in one shot.
        unsafe {
            drop(Box::from_raw(layout));
        }
    })
}

/// Borrow the laid-out cells. Pointer lifetime is tied to the
/// enclosing `ApfsLayout`; Swift must not retain the slice past
/// the layout handle's lifetime.
///
/// # Safety
/// `layout` must be NULL or a live layout handle from this module. Keep it
/// alive and unmodified while using the returned borrowed buffer.
#[no_mangle]
pub unsafe extern "C" fn apfs_layout_cells(layout: *const ApfsLayout) -> ApfsCellSlice {
    ffi_guard(
        ApfsCellSlice {
            cells: ptr::null(),
            count: 0,
        },
        move || {
            let empty = ApfsCellSlice {
                cells: ptr::null(),
                count: 0,
            };
            let Some(l) = (unsafe { layout.as_ref() }) else {
                return empty;
            };
            ApfsCellSlice {
                cells: l.cells.as_ptr(),
                count: l.cells.len() as u64,
            }
        },
    )
}

/// Number of cells in the layout. Convenience accessor — the
/// same value is on `ApfsCellSlice.count`.
///
/// # Safety
/// `layout` must be NULL or a live layout handle from this module. It must
/// not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_layout_cell_count(layout: *const ApfsLayout) -> u64 {
    ffi_guard(0, move || {
        let Some(l) = (unsafe { layout.as_ref() }) else {
            return 0;
        };
        l.cells.len() as u64
    })
}

/// Find the deepest cell containing `(x, y)`. Returns
/// `APFS_CELL_INVALID` (`u32::MAX`) if no cell does or
/// `(x, y)` is outside the laid-out rect. Sub-millisecond on a
/// /-class scan thanks to the 64×64 spatial hash; OK to call
/// every mousemove.
///
/// # Safety
/// `layout` must be NULL or a live layout handle from this module. It must
/// not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_layout_hit_test(layout: *const ApfsLayout, x: f32, y: f32) -> u32 {
    ffi_guard(APFS_CELL_INVALID, move || {
        let Some(l) = (unsafe { layout.as_ref() }) else {
            return APFS_CELL_INVALID;
        };
        l.hit_grid
            .hit_test(x, y, &l.cells)
            .unwrap_or(APFS_CELL_INVALID)
    })
}

// ─────────────────────────────────────────────────────────────
// Phase 5d: ext-list summary
// ─────────────────────────────────────────────────────────────

/// Opaque handle holding a `(rows, total_value, any_unclaimed)`
/// snapshot built from a subtree walk. Swift constructs via
/// `apfs_scan_ext_summary_new`, reads rows via `_count` /
/// `_row`, drops via `_free`.
pub struct ApfsExtSummaryHandle(pub(crate) ExtSummary);

/// One ext-list row, flattened for the C ABI. Strings are
/// borrowed (lifetime tied to the enclosing
/// `ApfsExtSummaryHandle`); `value_allocated == u64::MAX` is
/// the SR-019 None-collapse sentinel.
#[repr(C)]
#[derive(Copy, Clone)]
pub struct ApfsExtRow {
    pub ext: ApfsPathRef,
    pub value_logical: u64,
    pub value_allocated: u64,
    pub file_count: u32,
    /// Treemap palette colour, packed as 0xRRGGBB. Uses the former padding slot.
    pub fill_rgb: u32,
}

/// Construct the ext-list summary for the subtree rooted at
/// `node_idx`. `metric == 1` sorts by allocated; anything else
/// sorts by logical. Returns NULL on invalid scan / idx.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module, not mutated
/// or freed during the call. Free a non-NULL result with
/// `apfs_scan_ext_summary_free`. The result does not borrow from `scan`.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_new(
    scan: *const ApfsScan,
    node_idx: u32,
    metric: u32,
) -> *mut ApfsExtSummaryHandle {
    ffi_guard(ptr::null_mut(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return ptr::null_mut();
        };
        if (node_idx as usize) >= s.tree.nodes.len() {
            return ptr::null_mut();
        }
        let metric_enum = if metric == 1 {
            Metric::Allocated
        } else {
            Metric::Logical
        };
        let summary = ExtSummary::build(&s.tree, node_idx, metric_enum);
        Box::into_raw(Box::new(ApfsExtSummaryHandle(summary)))
    })
}

/// Drop the summary handle. Idempotent on NULL.
///
/// # Safety
/// `handle` must be NULL or an owning handle from `apfs_scan_ext_summary_new`,
/// not previously freed. All calls and borrowed views using it must be done.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_free(handle: *mut ApfsExtSummaryHandle) {
    ffi_guard((), move || {
        if handle.is_null() {
            return;
        }
        // SAFETY: caller obtained `handle` from `_new` and hasn't
        // freed it.
        unsafe {
            drop(Box::from_raw(handle));
        }
    })
}

/// Number of extension-summary rows. Returns 0 on NULL.
///
/// # Safety
/// `handle` must be NULL or a live extension-summary handle from this module.
/// It must not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_count(handle: *const ApfsExtSummaryHandle) -> u32 {
    ffi_guard(0, move || {
        let Some(h) = (unsafe { handle.as_ref() }) else {
            return 0;
        };
        h.0.rows.len() as u32
    })
}

/// Sum of the active-metric values across all rows. Used by
/// Swift for the per-row percent column. Returns 0 on
/// invalid handle.
///
/// # Safety
/// `handle` must be NULL or a live extension-summary handle from this module.
/// It must not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_total(handle: *const ApfsExtSummaryHandle) -> u64 {
    ffi_guard(0, move || {
        let Some(h) = (unsafe { handle.as_ref() }) else {
            return 0;
        };
        h.0.total_value
    })
}

/// True iff at least one contributing file's `allocated_size`
/// was None (SR-019 None-collapse). The Swift panel uses this
/// to caption the header subtitle.
///
/// # Safety
/// `handle` must be NULL or a live extension-summary handle from this module.
/// It must not be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_any_unclaimed(
    handle: *const ApfsExtSummaryHandle,
) -> bool {
    ffi_guard(false, move || {
        let Some(h) = (unsafe { handle.as_ref() }) else {
            return false;
        };
        h.0.any_unclaimed
    })
}

/// Fetch row `n`. Returns a zero-filled row if `n` is out of
/// range or the handle is NULL.
///
/// # Safety
/// `handle` must be NULL or a live extension-summary handle from this module.
/// Keep it alive and unmodified while using the returned borrowed bytes.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_ext_summary_row(
    handle: *const ApfsExtSummaryHandle,
    n: u32,
) -> ApfsExtRow {
    ffi_guard(
        ApfsExtRow {
            ext: ApfsPathRef {
                bytes: ptr::null(),
                len: 0,
            },
            value_logical: 0,
            value_allocated: APFS_ALLOCATED_TOTAL_UNCLAIMED,
            file_count: 0,
            fill_rgb: 0,
        },
        move || {
            let zero = ApfsExtRow {
                ext: ApfsPathRef {
                    bytes: ptr::null(),
                    len: 0,
                },
                value_logical: 0,
                value_allocated: APFS_ALLOCATED_TOTAL_UNCLAIMED,
                file_count: 0,
                fill_rgb: 0,
            };
            let Some(h) = (unsafe { handle.as_ref() }) else {
                return zero;
            };
            let idx = n as usize;
            if idx >= h.0.rows.len() {
                return zero;
            }
            let row = &h.0.rows[idx];
            let allocated = row
                .value_allocated
                .unwrap_or(APFS_ALLOCATED_TOTAL_UNCLAIMED);
            ApfsExtRow {
                ext: ApfsPathRef {
                    bytes: row.ext.as_ptr(),
                    len: row.ext.len() as u64,
                },
                value_logical: row.value_logical,
                value_allocated: allocated,
                file_count: row.file_count,
                fill_rgb: crate::render::category_color(&row.ext),
            }
        },
    )
}

/// `true` iff at least one entry has `allocated_size = Some(_)`.
/// The Swift UI uses this to gate the "Allocated" metric chip.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_allocated_available(scan: *const ApfsScan) -> bool {
    ffi_guard(false, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return false;
        };
        s.allocated_available
    })
}

/// `correctness_claim` (UTF-8, NUL-terminated). The returned
/// pointer is owned by `scan` and is valid until
/// `apfs_scan_free(scan)`. Swift must not free it.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed string.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_correctness_claim(scan: *const ApfsScan) -> *const c_char {
    ffi_guard(ptr::null(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return ptr::null();
        };
        s.correctness_claim.as_ptr()
    })
}

/// `SourceDescriptor.source_kind` (e.g. `"mounted_directory"`,
/// `"dmg_image"`). UTF-8, NUL-terminated; owned by `scan`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed string.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_source_kind(scan: *const ApfsScan) -> *const c_char {
    ffi_guard(ptr::null(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return ptr::null();
        };
        s.source_kind.as_ptr()
    })
}

/// `SourceDescriptor.requested_path`, the absolute path the user
/// asked us to scan. UTF-8, NUL-terminated; owned by `scan`.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed string.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_source_requested_path(scan: *const ApfsScan) -> *const c_char {
    ffi_guard(ptr::null(), move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return ptr::null();
        };
        s.source_requested_path.as_ptr()
    })
}

// ─────────────────────────────────────────────────────────────
// Walk-skip enumeration (audit r3 #F1)
//
// `parser_output.walk_skips` carries per-subtree skip notes
// (permission_denied, mount_boundary, non_utf8_name,
// depth_cap_reached, drec_cycle). The CLI's JSONL output
// already emits them, but the SwiftUI app saw nothing — a
// crafted image with a 1000-deep directory chain truncated
// silently in the treemap. These two accessors expose the
// list to Swift so the status bar can show a "N subtrees
// elided" banner.
//
// Mirrors `apfs_scan_ext_summary_*` shape: `_count` returns the
// row count and `_row(idx)` returns a borrowed (path, reason)
// pair. Strings are valid for the lifetime of the `ApfsScan`
// handle.
// ─────────────────────────────────────────────────────────────

/// Borrowed (path, reason) pair for one walk skip. Both strings
/// are `ApfsPathRef`-shaped: pointer + length, no NUL terminator,
/// owned by `ApfsScan`. UTF-8.
#[repr(C)]
#[derive(Copy, Clone)]
pub struct ApfsWalkSkipRow {
    pub path: ApfsPathRef,
    pub reason: ApfsPathRef,
}

/// Number of `walk_skip` rows recorded during the scan. 0 when
/// the scan completed cleanly.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. It must not
/// be mutated or freed during this call.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_walk_skip_count(scan: *const ApfsScan) -> u32 {
    ffi_guard(0, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return 0;
        };
        s.output.parser_output.walk_skips.len() as u32
    })
}

/// Fetch walk-skip row `n`. Returns an all-NULL row for out-of-
/// range indices or a NULL handle.
///
/// # Safety
/// `scan` must be NULL or a live scan handle from this module. Keep it alive
/// and unmodified while using the returned borrowed bytes.
#[no_mangle]
pub unsafe extern "C" fn apfs_scan_walk_skip_row(scan: *const ApfsScan, n: u32) -> ApfsWalkSkipRow {
    let zero = ApfsWalkSkipRow {
        path: ApfsPathRef {
            bytes: ptr::null(),
            len: 0,
        },
        reason: ApfsPathRef {
            bytes: ptr::null(),
            len: 0,
        },
    };
    ffi_guard(zero, move || {
        let Some(s) = (unsafe { scan.as_ref() }) else {
            return zero;
        };
        let idx = n as usize;
        let rows = &s.output.parser_output.walk_skips;
        if idx >= rows.len() {
            return zero;
        }
        let row = &rows[idx];
        ApfsWalkSkipRow {
            path: ApfsPathRef {
                bytes: row.path.as_ptr(),
                len: row.path.len() as u64,
            },
            reason: ApfsPathRef {
                bytes: row.reason.as_ptr(),
                len: row.reason.len() as u64,
            },
        }
    })
}

#[cfg(test)]
mod tests {
    //! Adversarial-input coverage for the FFI panic safety
    //! landed in commit 1eacf54. The in-module tests focus on
    //! `ffi_guard` itself — happy-path, sentinel on panic, and
    //! interaction with the thread-local error slot. Cross-
    //! binary lifecycle (process-isolated panic-hook installs,
    //! `apfs_last_error` clear-on-read) lives in
    //! `tests/diag_ffi.rs` so each case runs fresh.

    use super::*;

    fn small_output() -> crate::FallbackScanOutput {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("ΟΣ.txt"), b"content").unwrap();
        crate::fallback_scan_path_with_options(
            dir.path(),
            crate::FallbackOptions {
                skip_aggregates: true,
                ..Default::default()
            },
        )
        .unwrap()
    }

    fn error_message() -> String {
        let error = apfs_last_error();
        assert!(!error.is_null());
        unsafe { CStr::from_ptr(error) }
            .to_string_lossy()
            .into_owned()
    }

    #[test]
    fn msgpack_import_preserves_every_output_and_tree_field() {
        use std::io::Write;
        let output = small_output();
        let mut file = tempfile::NamedTempFile::new().unwrap();
        file.write_all(&rmp_serde::to_vec_named(&output).unwrap())
            .unwrap();
        let filename = CString::new(file.path().to_str().unwrap()).unwrap();
        // SAFETY: filename owns a valid C string throughout this call.
        let loaded = unsafe { apfs_scan_from_msgpack_file(filename.as_ptr()) };
        assert!(!loaded.is_null(), "{}", error_message_if_present());
        let direct = finalize_scan_handle(output.clone());
        assert!(!direct.is_null());
        unsafe {
            let loaded_ref = &*loaded;
            let direct_ref = &*direct;
            assert_eq!(loaded_ref.output, output);
            assert_eq!(
                format!("{:?}", loaded_ref.tree),
                format!("{:?}", direct_ref.tree)
            );
            assert_eq!(loaded_ref.correctness_claim, direct_ref.correctness_claim);
            assert_eq!(loaded_ref.source_kind, direct_ref.source_kind);
            assert_eq!(
                loaded_ref.source_requested_path,
                direct_ref.source_requested_path
            );
            assert_eq!(
                loaded_ref.allocated_available,
                direct_ref.allocated_available
            );
            assert_eq!(loaded_ref.real_available, direct_ref.real_available);
        }
        // SAFETY: both owning handles are live and their borrowed views are done.
        unsafe {
            apfs_scan_free(loaded);
            apfs_scan_free(direct);
        }
    }

    fn error_message_if_present() -> String {
        let error = apfs_last_error();
        if error.is_null() {
            String::new()
        } else {
            unsafe { CStr::from_ptr(error) }
                .to_string_lossy()
                .into_owned()
        }
    }

    #[test]
    fn msgpack_import_accepts_public_cli_permissions() {
        use std::io::Write;
        use std::os::unix::fs::PermissionsExt;
        let output = small_output();
        let mut file = tempfile::NamedTempFile::new().unwrap();
        file.write_all(&rmp_serde::to_vec_named(&output).unwrap())
            .unwrap();
        file.as_file()
            .set_permissions(std::fs::Permissions::from_mode(0o644))
            .unwrap();
        let filename = CString::new(file.path().to_str().unwrap()).unwrap();
        // SAFETY: filename owns a valid C string throughout this call.
        let scan = unsafe { apfs_scan_from_msgpack_file(filename.as_ptr()) };
        assert!(!scan.is_null());
        // SAFETY: scan is the original owning handle and has no borrowed views.
        unsafe { apfs_scan_free(scan) };
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn msgpack_import_refuses_symlinks_and_fifos_without_blocking() {
        use std::os::unix::fs::symlink;
        let dir = tempfile::tempdir().unwrap();
        let target = dir.path().join("scan.msgpack");
        std::fs::write(&target, rmp_serde::to_vec_named(&small_output()).unwrap()).unwrap();
        let link = dir.path().join("link.msgpack");
        symlink(&target, &link).unwrap();
        let link = CString::new(link.to_str().unwrap()).unwrap();
        // SAFETY: link owns a valid C string throughout this call.
        assert!(unsafe { apfs_scan_from_msgpack_file(link.as_ptr()) }.is_null());
        assert!(error_message().contains("read"));
        let fifo = CString::new(dir.path().join("fifo").to_str().unwrap()).unwrap();
        assert_eq!(unsafe { libc::mkfifo(fifo.as_ptr(), 0o600) }, 0);
        // SAFETY: fifo owns a valid C string throughout this call.
        assert!(unsafe { apfs_scan_from_msgpack_file(fifo.as_ptr()) }.is_null());
        assert!(error_message().contains("not a regular file"));
    }

    #[test]
    fn msgpack_import_refuses_corruption_and_invalid_c_string_fields() {
        use std::io::Write;
        let mut file = tempfile::NamedTempFile::new().unwrap();
        file.write_all(b"not msgpack").unwrap();
        let filename = CString::new(file.path().to_str().unwrap()).unwrap();
        // SAFETY: filename owns a valid C string throughout this call.
        assert!(unsafe { apfs_scan_from_msgpack_file(filename.as_ptr()) }.is_null());
        assert!(error_message().contains("decode"));
        for field in 0..3 {
            let mut output = small_output();
            match field {
                0 => output.correctness_claim.push('\0'),
                1 => output.parser_output.source.source_kind.push('\0'),
                _ => output.parser_output.source.requested_path = "invalid\0path".into(),
            }
            assert!(finalize_scan_handle(output).is_null());
            assert!(error_message().contains("NUL"));
        }
    }

    #[test]
    fn search_matches_canonical_caseless_unicode() {
        let mut output = small_output();
        for (i, path) in ["Straße.txt", "Café.txt"].into_iter().enumerate() {
            output.parser_output.entries.push(crate::NamespaceEntry {
                path: path.into(),
                entry_kind: crate::EntryKind::File,
                file_id: i as u64,
                logical_size: 1,
                allocated_size: Some(1),
                real_size: Some(1),
                symlink_target: None,
            });
        }
        let scan = finalize_scan_handle(output);
        assert!(!scan.is_null());
        for (expected_name, queries) in [
            (
                "ΟΣ.txt",
                &[
                    "ΟΣ", "ος", "οσ", "Σ", "σ", "ς", "Ο", "ο", "ΟΣ.TXT", "ος.txt",
                ][..],
            ),
            (
                "Straße.txt",
                &["STRASSE", "strasse", "STRASS", "straße"][..],
            ),
            (
                "Café.txt",
                &["CAFÉ", "café", "CAFE\u{301}", "cafe\u{301}", "CAF"][..],
            ),
        ] {
            for query in queries {
                let query = CString::new(*query).unwrap();
                // SAFETY: scan and query stay live, and the one matching result
                // owns its index buffer. Borrowed views are used before either
                // owner is freed, and results is freed exactly once.
                unsafe {
                    let results = apfs_scan_search_names(scan, query.as_ptr());
                    assert!(!results.is_null());
                    assert_eq!(apfs_search_results_match_count(results), 1, "{query:?}");
                    let index = *apfs_search_results_match_indices(results);
                    let name = apfs_scan_node_name(scan, index);
                    let bytes = std::slice::from_raw_parts(name.bytes, name.len as usize);
                    assert_eq!(bytes, expected_name.as_bytes());
                    apfs_search_results_free(results);
                }
            }
        }
        // SAFETY: scan is the original owning handle and all borrowed views are done.
        unsafe { apfs_scan_free(scan) };
    }

    #[test]
    fn ffi_guard_returns_closure_value_when_no_panic() {
        let result = ffi_guard(0_u32, || 42);
        assert_eq!(result, 42);
    }

    #[test]
    fn ffi_guard_returns_sentinel_on_panic() {
        // `catch_unwind` is active in debug builds (cargo test
        // runs debug by default); release builds with
        // `panic = "abort"` would abort the test process and
        // never reach this assertion.
        #[cfg(debug_assertions)]
        {
            let result = ffi_guard(99_u32, || panic!("ffi_guard test panic"));
            assert_eq!(result, 99, "panic should yield the sentinel");
        }
    }

    #[test]
    fn ffi_guard_with_pointer_sentinel() {
        // Mirror the pattern the real FFI uses: returning a
        // NULL pointer on bad input or panic. Confirms the
        // generic over `R = *mut T` compiles and behaves.
        let sentinel: *mut ApfsScan = ptr::null_mut();
        #[cfg(debug_assertions)]
        {
            let result = ffi_guard(sentinel, || -> *mut ApfsScan {
                panic!("simulated parser failure")
            });
            assert!(result.is_null());
        }
        // Non-panic path: returns whatever the closure made.
        let result = ffi_guard(sentinel, || -> *mut ApfsScan { sentinel });
        assert!(result.is_null());
    }

    /// Round-2 audit #N1 regression: the `path_cache` Mutex must
    /// recover from a poison instead of permanently returning
    /// `(NULL, 0)` to every subsequent `apfs_scan_node_path`
    /// call. We force a poison by panicking while holding the
    /// guard, then confirm we can still read and write the map
    /// afterwards.
    #[test]
    fn path_cache_recovers_from_poison() {
        use std::collections::HashMap;
        use std::sync::Mutex;

        let cache: Mutex<HashMap<u32, Box<str>>> = Mutex::new(HashMap::new());

        // Poison the mutex: panic while the guard is held.
        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut guard = cache.lock().unwrap();
            guard.insert(7, Box::from("pre-poison"));
            panic!("synthetic panic to poison the mutex");
        }));

        // Sanity: the mutex is poisoned.
        assert!(
            cache.lock().is_err(),
            "mutex should be poisoned after panic"
        );

        // The recovery idiom we ship in `apfs_scan_node_path`.
        let mut guard = cache
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        // Pre-poison entry survived.
        assert_eq!(guard.get(&7).map(|s| s.as_ref()), Some("pre-poison"));
        // And we can still write.
        guard.insert(9, Box::from("post-poison"));
        assert_eq!(guard.get(&9).map(|s| s.as_ref()), Some("post-poison"));
    }
}
